<article class="journal-article wrap">
<?= component('breadcrumbs',['items'=>[['label'=>'Inicio','href'=>'/'],['label'=>'Historias','href'=>'/historias'],['label'=>$entry['label']]]]) ?>
<header class="journal-article-heading" data-sequence><span class="micro-label"><?= icon('book') ?> <?= e($entry['label']) ?></span><h1><?= e($entry['title']) ?>.</h1><p><?= e($entry['lead']) ?></p><span class="journal-byline">Reflexiones de <?= e(site_name()) ?></span></header>
<figure class="journal-article-cover"><img src="/assets/img/<?= e($entry['image']) ?>" width="1600" height="900" alt="<?= e($entry['title']) ?>" fetchpriority="high"></figure>
<div class="journal-reading"><?php foreach($entry['paragraphs'] as $index=>$paragraph): ?><p><?= e($paragraph) ?></p><?php if($index===1): ?><blockquote class="reveal"><?= e($entry['quote']) ?></blockquote><?php endif ?><?php endforeach ?><div class="journal-reading-close"><span><?= icon('heart') ?></span><h2>Cada historia puede<br><em>abrir una conversación.</em></h2><a class="btn btn-primary" href="/contacto">Compartir una idea <?= icon('message') ?></a></div></div>
